#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    /* Simple postfix expression evaluator matching the observed behavior */
    long stack[64];
    int top = 0;

    if (argc < 2) {
        puts("ERROR");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        char *endptr;
        long val = strtol(arg, &endptr, 10);
        if (*arg != '\0' && *endptr == '\0') {
            /* token is a valid integer */
            if (top >= 64) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = val;
            continue;
        }
        /* check for single‑character operators */
        if (strlen(arg) == 1 && strchr("+-*/", arg[0])) {
            if (top < 2) {
                puts("ERROR");
                return 0;
            }
            long b = stack[--top];
            long a = stack[--top];
            long result;
            switch (arg[0]) {
                case '+': result = a + b; break;
                case '-': result = a - b; break;
                case '*': result = a * b; break;
                case '/':
                    if (b == 0) {
                        puts("ERROR");
                        return 0;
                    }
                    result = a / b;
                    break;
                default: /* never reached */ result = 0; break;
            }
            stack[top++] = result;
            continue;
        }
        /* any other token is an error */
        puts("ERROR");
        return 0;
    }

    if (top == 1) {
        printf("%ld\n", stack[0]);
    } else {
        puts("ERROR");
    }
    return 0;
}
